
/* ============ تنقل ============ */
let V={n:'patients'};
function go(n,p){V={n,...p};render();window.scrollTo(0,0)}
function render(){
 const tabs=[['patients','المرضى'],['catalog','التحاليل'],['settings','الإعدادات']];
 const act=['patient','visit','edit','view'].includes(V.n)?'patients':V.n;
 $('nav').innerHTML=tabs.map(([k,l])=>`<button class="${act===k?'on':''}" onclick="go('${k}')">${l}</button>`).join('');
 ({patients:vPatients,patient:vPatient,edit:vEdit,view:vView,catalog:vCatalog,settings:vSettings})[V.n]();
}

/* ============ المرضى ============ */
function vPatients(){
 $('app').innerHTML=`<div class="row"><input class="grow" id="q" placeholder="ابحث بالاسم أو رقم التليفون أو رقم الزيارة" oninput="listP()" onkeydown="if(event.key==='Enter')pEnter()" autocomplete="off"><button class="btn" onclick="pForm()">+ مريض جديد</button></div>
 <div class="muted" style="margin:8px 2px" id="cnt"></div><div id="pl"></div>`;listP();if(!matchMedia('(pointer:coarse)').matches)$('q').focus()}
function dg(x){return String(x||'').replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/\D/g,'')}
function pk(x){return dg(x).replace(/^(0020|20|0)/,'')}
let LQ=[];
function listP(){const q0=($('q')?.value||'').trim(),q=q0.toLowerCase();const ph=/^[+\d\s\-٠-٩]+$/.test(q0)&&dg(q0).length>=2,qk=pk(q0),qd=dg(q0);
 const vm=ph&&qd.length>=6?S.visits.filter(v=>v.no&&v.no.includes(qd)):[];LQ=vm;
 let a=S.patients.filter(p=>!q||(ph?((qk&&pk(p.phone).includes(qk))||vm.some(v=>v.pid===p.id)||p.name.toLowerCase().includes(q)):(p.name.toLowerCase().includes(q)||(p.phone||'').includes(q))));
 const last=p=>S.visits.filter(v=>v.pid===p.id).map(v=>v.date).sort().pop()||'';
 a.sort((x,y)=>(last(y)||y.created).localeCompare(last(x)||x.created));
 $('cnt').textContent=S.patients.length+' مريض'+(q?' - النتيجة: '+a.length:'');
 $('pl').innerHTML=a.length?a.map(p=>{const n=S.visits.filter(v=>v.pid===p.id).length;
 return `<div class="card item" onclick="go('patient',{id:'${p.id}'})"><div><b>${esc(p.name)}</b><span class="muted">${esc(p.phone||'بدون رقم')} ${hasAge(p)?' - '+esc(ageTxt(p)):''} ${gl(p.gender)?' - '+gl(p.gender):''}</span></div><span class="tag">${n} زيارة</span></div>`}).join(''):`<div class="empty">${S.patients.length?'مفيش نتائج':'لسه مفيش مرضى. دوس "مريض جديد" وابدأ.'}${ph&&qk.length>=9?`<br><button class="btn" style="margin-top:10px" onclick="pForm('','${esc(q0)}')">+ مريض جديد بالرقم ${esc(q0)}</button>`:''}</div>`}
function pEnter(){const e=LQ.find(v=>v.no===dg($('q').value));if(e)return go('view',{id:e.id});const r=document.querySelectorAll('#pl .item');if(r.length===1)r[0].click()}
function pForm(id,ph){const p=S.patients.find(x=>x.id===id)||{phone:ph||''};
 $('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeM()"><div><h2>${id?'تعديل بيانات المريض':'مريض جديد'}</h2>
 <label>الاسم *</label><input id="fn" value="${esc(p.name||'')}">
 <label>رقم التليفون (واتساب)</label><input id="fp" type="tel" inputmode="tel" value="${esc(p.phone||'')}" placeholder="01xxxxxxxxx">
 <div class="row"><div class="grow"><label>السن</label><input id="fa" type="number" inputmode="decimal" min="0" step="any" value="${esc(p.age??'')}"></div>
 <div class="grow"><label>الوحدة</label><select id="fau"><option value="y" ${(p.au||'y')==='y'?'selected':''}>سنة</option><option value="m" ${p.au==='m'?'selected':''}>شهر</option><option value="d" ${p.au==='d'?'selected':''}>يوم</option></select></div>
 <div class="grow"><label>النوع</label><select id="fg"><option value="M" ${p.gender!=='F'?'selected':''}>ذكر</option><option value="F" ${p.gender==='F'?'selected':''}>أنثى</option></select></div></div>
 <label>ملاحظات</label><input id="fno" value="${esc(p.note||'')}">
 <div class="row" style="margin-top:14px"><button class="btn grow" onclick="pSave('${id||''}')">حفظ</button><button class="btn s" onclick="closeM()">إلغاء</button></div></div></div>`;$('fn').focus()}
function closeM(){$('modal').innerHTML=''}
function pSave(id){const name=$('fn').value.trim();if(!name){toast('اكتب الاسم');return}
 const d={name,phone:$('fp').value.trim(),age:$('fa').value.trim(),au:$('fau').value,gender:$('fg').value,note:$('fno').value.trim()};
 if(id)Object.assign(S.patients.find(x=>x.id===id),d);else{d.id=uid('p');d.created=today();S.patients.push(d);id=d.id}
 save();closeM();go('patient',{id})}
function vPatient(){const p=S.patients.find(x=>x.id===V.id);if(!p)return go('patients');
 const vs=S.visits.filter(v=>v.pid===p.id).sort((a,b)=>b.date.localeCompare(a.date));
 $('app').innerHTML=`<div class="card"><h2 style="margin-top:0">${esc(p.name)}</h2>
 <div class="muted">${esc(p.phone||'بدون رقم')} ${hasAge(p)?' - '+esc(ageTxt(p)):''} - ${gl(p.gender)}</div>${p.note?`<div class="muted">${esc(p.note)}</div>`:''}
 <div class="row" style="margin-top:10px"><button class="btn" onclick="go('edit',{pid:'${p.id}'})">+ زيارة / تحاليل جديدة</button>
 <button class="btn s sm" onclick="pForm('${p.id}')">تعديل البيانات</button><button class="btn d sm" onclick="pDel('${p.id}')">حذف المريض</button></div></div>
 <h3>سجل الزيارات (${vs.length})</h3>${vs.length?vs.map(v=>`<div class="card item" onclick="go('view',{id:'${v.id}'})"><div><b>${fd(v.date)}</b><span class="muted">${v.items.map(i=>esc(i.name)).slice(0,4).join('، ')}${v.items.length>4?' ...':''}</span></div><span class="tag">${v.items.length} تحليل${v.items.some(i=>flag(i,agk(p)))?' ⚠':''} ${v.rel?'✅':'مسودة'}</span></div>`).join(''):'<div class="empty">مفيش زيارات لسه</div>'}
 ${trend(p,vs)}`}
function trend(p,vs){ // مقارنة آخر قيم لنفس التحليل
 if(vs.length<2)return '';const m={};vs.forEach(v=>v.items.forEach(i=>{if(i.type==='num'&&i.value!=='')(m[i.name]=m[i.name]||[]).push([v.date,i.value,flag(i,agk(p))])}));
 const k=Object.keys(m).filter(x=>m[x].length>1);if(!k.length)return '';
 return `<h3>تطور التحاليل المتكررة</h3><div class="card"><table><tr><th>التحليل</th><th>النتائج (الأحدث أولًا)</th></tr>${k.map(n=>`<tr><td class="l">${esc(n)}</td><td class="l">${m[n].slice(0,6).map(x=>`<span class="${x[2]?'hi':''}">${esc(x[1])}</span>`).join(' ← ')}</td></tr>`).join('')}</table></div>`}
function pDel(id){if(!confirm('تحذف المريض وكل نتايجه؟ مينفعش ترجعها (إلا من نسخة احتياطية).'))return;
 S.patients=S.patients.filter(p=>p.id!==id);S.visits=S.visits.filter(v=>v.pid!==id);save();go('patients')}

/* ============ إدخال زيارة ============ */
let D=null; // مسودة
function vEdit(){
 if(!D||D.key!==(V.id||'n'+V.pid)){const v=V.id&&S.visits.find(x=>x.id===V.id);
  D=v?{key:V.id,id:v.id,no:v.no,doc:v.doc||'',pid:v.pid,date:v.date,notes:v.notes||'',ph:v.ph||[],hist:v.hist,cm:v.cm,paid:v.paid||'',disc:v.disc||'',items:JSON.parse(JSON.stringify(v.items))}:{key:'n'+V.pid,pid:V.pid,doc:'',date:today(),notes:'',paid:'',disc:'',items:[]}}
 const p=S.patients.find(x=>x.id===D.pid);
 $('app').innerHTML=`<div class="card"><b>${esc(p.name)}</b> <span class="muted">${hasAge(p)?ageTxt(p)+' - ':''}${gl(p.gender)}</span>${V.id&&(S.visits.find(x=>x.id===V.id)||{}).rel?'<div style="color:#b42318;font-weight:bold;margin-top:6px">⚠ التقرير معتمد. أي تعديل في النتائج أو التعليقات هيلغي الاعتماد.</div>':''}
 <label>تاريخ الزيارة</label><input type="date" id="dd" value="${D.date}" onchange="D.date=this.value">
 <label>الطبيب المعالج (اختياري، بيظهر في التقرير)</label><input id="dd2" list="dl" value="${esc(D.doc||'')}" oninput="D.doc=this.value" placeholder="د. ..."><datalist id="dl">${[...new Set(S.visits.map(x=>x.doc).filter(Boolean))].map(x=>`<option value="${esc(x)}">`).join('')}</datalist></div>
 <h3>١) اختار التحاليل</h3><input id="tq" autocomplete="off" placeholder="اكتب اسم التحليل أو اختصاره (CBC, TSH, FBS ...)" oninput="sug()" onkeydown="if(event.key==='Enter'){event.preventDefault();sugGo()}"><div id="sg"></div><div class="muted" style="margin:8px 0 2px">أو اختار من القوائم:</div><div id="pk"></div>
 <h3>٢) النتائج</h3><div class="card" id="phc"></div><div class="card" id="rs"></div>
 <div class="card"><label>تعليقات إرشادية (تتولد تلقائيًا من التحاليل مع مراجع الإرشادات - راجعها وعدّلها)</label><textarea id="cm" rows="7" style="direction:ltr;text-align:left" oninput="D.cm=this.value">${esc(D.cm!==undefined?D.cm:autoCm(D.items))}</textarea><button class="btn s sm" onclick="D.cm=undefined;$('cm').value=autoCm(D.items)">↻ إعادة التوليد التلقائي</button></div>
 ${D.items.some(i=>/^prothrombin time/i.test(i.name||''))?'<div class="card"><button class="btn s sm" onclick="ptCalc()">🧮 احسب INR و % من جدول PT (كنترول 12 ثانية)</button><div class="muted" style="font-size:12px">بيقرأ نتيجة Prothrombin Time ويكتب INR و % ومعاهم كنترول 12. راجع قبل الاعتماد.</div></div>':''}
 <div class="card"><label>ملاحظات تظهر في التقرير</label><textarea id="nt" rows="2" oninput="D.notes=this.value">${esc(D.notes)}</textarea>
 <div class="row"><div class="grow"><label>خصم (جنيه)</label><input type="number" inputmode="decimal" value="${esc(D.disc)}" oninput="D.disc=this.value;tot()"></div><div class="grow"><label>المدفوع (جنيه)</label><input type="number" inputmode="decimal" value="${esc(D.paid)}" oninput="D.paid=this.value;tot()"></div></div>
 <div id="tt" style="margin-top:8px;font-weight:bold"></div></div>
 <div class="row"><button class="btn grow" onclick="vSave()">حفظ وعرض التقرير</button><button class="btn s" onclick="D=null;go('patient',{id:'${p.id}'})">إلغاء</button></div>`;
 pick();rs();tot();phr()}
let SG=[];
function sug(){const q=($('tq').value||'').trim().toLowerCase();const e=$('sg');if(!q){SG=[];e.innerHTML='';return}
 const qc=nk(q),sel=new Set(D.items.map(i=>i.tid));const sc=[];
 S.tests.forEach(t=>{const n=t.name.toLowerCase();let s=-1;if(n.startsWith(q))s=0;else if(n.split(/[^a-z0-9]+/).some(w=>w.startsWith(q)))s=1;else if(n.includes(q))s=2;else if(qc&&nk(n).includes(qc))s=3;else if(CATS[t.cat]&&CATS[t.cat].includes(q))s=4;if(s>=0)sc.push([s,n.length,t])});
 sc.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);SG=sc.slice(0,12).map(x=>x[2]);
 e.innerHTML=SG.length?'<div class="card sg">'+SG.map(t=>`<button type="button" class="sgi" onclick="sugAdd('${t.id}')"><span class="n">${esc(t.name)}</span><span class="muted">${sel.has(t.id)?'\u2713 ':''}${esc(t.unit||'')} ${esc(CATS[t.cat]||'')}</span></button>`).join('')+'</div>':'<div class="empty">مفيش تحليل بالاسم ده. ضيفه من تبويب التحاليل.</div>'}
function sugAdd(id){if(!D.items.some(i=>i.tid===id))tog(id,true);$('tq').value='';SG=[];$('sg').innerHTML='';$('tq').focus();toast('تمت الإضافة')}
function sugGo(){if(SG.length)sugAdd(SG[0].id)}
function pick(){const q='';const sel=new Set(D.items.map(i=>i.tid));
 const groups=Object.keys(CATS).map(c=>({c,l:S.tests.filter(t=>t.cat===c&&(!q||t.name.toLowerCase().includes(q)||CATS[c].includes(q)))})).filter(g=>g.l.length);
 $('pk').innerHTML=groups.map(g=>`<details ${q||g.l.some(t=>sel.has(t.id))?'open':''}><summary>${CATS[g.c]} (${g.l.length})</summary><div class="card" style="margin:4px 0">${g.l.map(t=>`<label class="chk"><input type="checkbox" ${sel.has(t.id)?'checked':''} onchange="tog('${t.id}',this.checked)"><span class="n" style="direction:ltr;text-align:right">${esc(t.name)}</span>${t.price?`<span class="muted">${t.price} ج</span>`:''}</label>`).join('')}</div></details>`).join('')||'<div class="empty">مفيش تحليل بالاسم ده. ضيفه من تبويب التحاليل.</div>'}
function tog(id,on){if(on){const t=S.tests.find(x=>x.id===id);D.items.push({tid:t.id,name:t.name,cat:t.cat,type:t.type,unit:t.unit,low:t.low,high:t.high,lowF:t.lowF,highF:t.highF,lowN:t.lowN,highN:t.highN,lowI:t.lowI,highI:t.highI,normal:t.normal,price:t.price,rdef:t.rdef,value:t.type==='txt'?(t.normal||''):''})}
 else D.items=D.items.filter(i=>i.tid!==id);rs();tot()}
function rs(){const p=S.patients.find(x=>x.id===D.pid);
 $('rs').innerHTML=D.items.length?D.items.map((i,k)=>`<div class="res ${flag(i,agk(p))?'hi':''}" id="rr${k}"><div><span style="direction:ltr;display:block;text-align:right">${esc(i.name)}</span><span class="muted" style="direction:ltr;display:block;text-align:right">${esc(refText(i,agk(p)))} ${esc(i.unit)}${i.rdef?' <span class="tag" style="background:#fff3cd;color:#8a6d00">⚠ مدى افتراضي - راجعه</span>':''}${i.imp?' <span class="tag" style="background:#e0f2fe;color:#075985">📥 مستورد - راجعه</span>':''}</span></div>
 <input value="${esc(i.value)}" placeholder="النتيجة" ${i.type==='num'?'inputmode="decimal"':''} oninput="D.items[${k}].value=this.value;D.items[${k}].imp=0;document.getElementById('rr${k}').classList.toggle('hi',!!flag(D.items[${k}],'${agk(p)}'))"></div>`).join(''):'<div class="empty">اختار تحاليل من فوق</div>'}
function newNo(d){const k=String(d||today()).replace(/-/g,'').slice(2);let n=S.visits.filter(x=>x.no&&x.no.startsWith(k)).length+1,c;do{c=k+String(n++).padStart(2,'0')}while(S.visits.some(x=>x.no===c));return c}
function hv(v){const t=JSON.stringify([v.pid,v.date,v.cm,v.notes||'',v.doc||'',v.items.map(i=>[i.tid,i.name,i.value,i.low,i.high,i.lowF,i.highF,i.normal,i.unit].concat(i.lowN!==undefined||i.highN!==undefined||i.lowI!==undefined||i.highI!==undefined?[i.lowN,i.highN,i.lowI,i.highI]:[]).concat(i.pr?['pr',i.pr.l,i.pr.h]:[]))]);let h=5381;for(let k=0;k<t.length;k++)h=((h<<5)+h+t.charCodeAt(k))|0;return String(h)}
function revForm(id){const v=S.visits.find(x=>x.id===id),p=S.patients.find(x=>x.id===v.pid);const rd=v.items.filter(i=>i.rdef);
 $('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeM()"><div><h2>راجع واعتمد التقرير</h2><div class="muted">التعليقات والمدى الافتراضي مسودات. بعد الاعتماد التقرير بيتجمّد (ما يتغيرش لو المكتبة اتحدثت)، ويطلع بالختم والتوقيع وتقدر تبعته على واتساب. أي تعديل بعد كده بيلغي الاعتماد.</div>
 <label>التعليقات (عدّلها لو لازم، وده النص اللي هيتجمّد)</label><textarea id="rvc" rows="8" style="direction:ltr;text-align:left">${esc(v.cm!==undefined?v.cm:autoCm(v.items))}</textarea>
 ${rd.length?`<div class="card" style="background:#fff3cd;color:#6b5300;margin-top:8px"><b>مدى افتراضي لم يُراجع (${rd.length}):</b><br>${rd.map(i=>esc(i.name)+': '+esc(refText(i,agk(p)))+' '+esc(i.unit)).join('<br>')}</div>`:''}
 <label class="chk"><input type="checkbox" class="rvk" onchange="rvChk()"><span>راجعت النتائج وهي صحيحة</span></label>
 <label class="chk"><input type="checkbox" class="rvk" onchange="rvChk()"><span>راجعت التعليقات وهي مناسبة للحالة</span></label>
 ${rd.length?`<label class="chk"><input type="checkbox" class="rvk" onchange="rvChk()"><span>راجعت المدى الافتراضي وهو مناسب للجهاز والكيت</span></label>`:''}
 <div class="row" style="margin-top:12px"><button class="btn grow" id="rvb" disabled onclick="revDo('${id}')">اعتماد التقرير</button><button class="btn s" onclick="closeM()">إلغاء</button></div></div></div>`}
function rvChk(){$('rvb').disabled=![...document.querySelectorAll('.rvk')].every(x=>x.checked)}
function revDo(id){const v=S.visits.find(x=>x.id===id);v.cm=$('rvc').value;v.rel={at:new Date().toISOString(),by:S.settings.owner||'',h:'',};v.rel.h=hv(v);save();closeM();render();toast('تم الاعتماد')}
function vno(v){return v.no||String(v.id).replace(/[^a-z0-9]/gi,'').slice(-6).toUpperCase()}
function sum(it){return it.reduce((a,i)=>a+(+i.price||0),0)}
function tot(){const s=sum(D.items),d=+D.disc||0,n=s-d,pd=+D.paid||0;if($('tt'))$('tt').textContent=s?`الإجمالي ${s} - الخصم ${d} = ${n} ج | المتبقي ${n-pd} ج`:''}
function vSave(){if(!D.items.length){toast('اختار تحليل واحد على الأقل');return}
 const v={id:D.id||uid('v'),ph:D.ph&&D.ph.length?D.ph:undefined,hist:D.hist||undefined,no:D.no,doc:(D.doc||'').trim(),pid:D.pid,date:D.date||today(),notes:D.notes,cm:D.cm,paid:D.paid,disc:D.disc,items:D.items};
 const i=S.visits.findIndex(x=>x.id===v.id);if(!v.no)v.no=newNo(v.date);if(i>=0){const o=S.visits[i];if(o.rel){if(hv(v)===o.rel.h)v.rel=o.rel;else toast('التعديل ألغى الاعتماد. التقرير رجع مسودة لحد ما تراجعه وتعتمده')}}if(i>=0)S.visits[i]=v;else S.visits.push(v);save();D=null;go('view',{id:v.id})}

/* ============ عرض زيارة ============ */
function vView(){const v=S.visits.find(x=>x.id===V.id);if(!v)return go('patients');const p=S.patients.find(x=>x.id===v.pid);
 const cats=Object.keys(CATS).filter(c=>v.items.some(i=>(i.cat||'oth')===c));const s=sum(v.items),n=s-(+v.disc||0);
 $('app').innerHTML=`<div class="card"><b>${esc(p.name)}</b> <span class="muted">${hasAge(p)?ageTxt(p)+' - ':''}${gl(p.gender)} - ${fd(v.date)}</span>
 <div class="muted">رقم الزيارة: ${esc(vno(v))}${v.doc?' - الطبيب المعالج: '+esc(v.doc):''}</div>
 ${v.rel?`<div style="margin-top:6px;color:#1a7f37;font-weight:bold">✅ معتمد ${esc(fd(v.rel.at.slice(0,10)))}${v.rel.by?' - '+esc(v.rel.by):''}</div>${autoCm(v.items)!==v.cm?`<div class="muted" style="margin-top:4px">المكتبة فيها تعليقات أحدث من المعتمدة. التقرير المعتمد ما اتغيرش. <a href="#" onclick="report('${v.id}',{draft:1,cm:autoCm(S.visits.find(x=>x.id==='${v.id}').items)});return false">شوف نسخة مسودة بالتعليقات الجديدة</a></div>`:''}`:`<div style="margin-top:6px;color:#b42318;font-weight:bold">⚠ مسودة غير معتمدة (التقرير بيطلع بعلامة DRAFT وبدون ختم أو توقيع)</div><button class="btn w sm" style="margin-top:6px" onclick="revForm('${v.id}')">✅ راجع واعتمد</button>`}
 <div class="row" style="margin-top:10px"><button class="btn s sm" onclick="refreshVisit('${v.id}')">🔄 تحديث نطاقات الأطفال</button><button class="btn w" onclick="report('${v.id}')">📄 تقرير PDF / واتساب</button><button class="btn s sm" onclick="printR('${v.id}',false)">🖨 طباعة ورق أبيض</button><button class="btn s sm" onclick="printR('${v.id}',true)">🖨 طباعة ورق الليتر هيد</button><button class="btn s sm" onclick="lblForm('${v.id}')">🏷 ملصقات الأنابيب</button><button class="btn s sm" onclick="go('edit',{id:'${v.id}',pid:'${p.id}'})">تعديل النتائج</button><button class="btn s sm" onclick="go('patient',{id:'${p.id}'})">ملف المريض</button><button class="btn d sm" onclick="vDel('${v.id}')">حذف</button></div></div>
 <div class="card" style="overflow-x:auto;direction:ltr"><table class="ltr"><tr><th class="l">Test</th><th class="l">Result</th><th class="l">Unit</th><th class="l">Reference</th></tr>
 ${cats.map(c=>`<tr><td colspan="4" style="background:#f4f7f7;font-weight:bold;color:var(--td)">${CATS[c]}</td></tr>`+v.items.filter(i=>(i.cat||'oth')===c).map(i=>{const f=flag(i,agk(p));return `<tr><td class="l">${esc(i.name)}</td><td class="l ${f?'hi':''}">${esc(i.value)||'-'} ${f==='H'?'▲':f==='L'?'▼':f?'●':''}</td><td class="l">${esc(i.unit)}</td><td class="l">${esc(refText(i,agk(p)))}</td></tr>`}).join('')).join('')}</table></div>
 ${v.notes?`<div class="card"><b>ملاحظات:</b> ${esc(v.notes)}</div>`:''}${s?`<div class="card muted">الإجمالي ${s} - الخصم ${+v.disc||0} = <b>${n} ج</b> | المدفوع ${+v.paid||0} | المتبقي ${n-(+v.paid||0)}</div>`:''}`}
function vDel(id){if(!confirm('تحذف الزيارة دي؟'))return;const v=S.visits.find(x=>x.id===id);S.visits=S.visits.filter(x=>x.id!==id);save();go('patient',{id:v.pid})}

/* ============ كتالوج التحاليل ============ */
function vCatalog(){
 $('app').innerHTML=`<div class="row"><input class="grow" id="cq" placeholder="ابحث في التحاليل (اكتب: افتراضي لعرض المدى الافتراضي اللي محتاج مراجعة)" oninput="listC()"><button class="btn" onclick="tForm()">+ تحليل جديد</button></div><div id="cl" style="margin-top:10px"></div>`;listC()}
function listC(){const q=($('cq')?.value||'').trim().toLowerCase();
 $('cl').innerHTML=Object.keys(CATS).map(c=>{const l=S.tests.filter(t=>t.cat===c&&(q==='افتراضي'?t.rdef:(!q||t.name.toLowerCase().includes(q))));if(!l.length)return '';
 return `<details ${q?'open':''}><summary>${CATS[c]} (${l.length})</summary><div class="card" style="margin:4px 0"><table>${l.map(t=>`<tr onclick="tForm('${t.id}')" style="cursor:pointer"><td class="l">${esc(t.name)}</td><td class="l muted">${esc(refText(t,'M'))} ${esc(t.unit)}${t.rdef?' <span class="tag" style="background:#fff3cd;color:#8a6d00">افتراضي</span>':''}</td><td>${t.price?t.price+' ج':'<span class="muted">بدون سعر</span>'}</td></tr>`).join('')}</table></div></details>`}).join('')||'<div class="empty">مفيش نتائج</div>'}
function tForm(id){const t=S.tests.find(x=>x.id===id)||{cat:'oth',type:'num',unit:'',low:'',high:'',lowF:'',highF:'',normal:'',price:''};
 $('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeM()"><div><h2>${id?'تعديل تحليل':'تحليل جديد'}</h2>${t.rdef?'<div class="card" style="background:#fff3cd;color:#6b5300">⚠ المدى ده افتراضي (قيم عامة للبالغين) ومش مراجَع. راجعه مع الكيت/الجهاز عندك، وعدّله لو مختلف، ولما تدوس حفظ العلامة بتتشال.</div>':''}
 <label>اسم التحليل *</label><input id="tn" dir="ltr" value="${esc(t.name||'')}">
 <div class="row"><div class="grow"><label>القسم</label><select id="tc">${Object.entries(CATS).map(([k,l])=>`<option value="${k}" ${t.cat===k?'selected':''}>${l}</option>`).join('')}</select></div>
 <div class="grow"><label>السعر (جنيه)</label><input id="tpr" type="number" inputmode="decimal" value="${esc(t.price)}"></div></div>
 <label>نوع النتيجة</label><select id="ty" onchange="tt()"><option value="num" ${t.type==='num'?'selected':''}>رقم (له مدى طبيعي)</option><option value="txt" ${t.type==='txt'?'selected':''}>كلام (Positive / Negative ...)</option></select>
 <div id="tn1"><div class="row"><div class="grow"><label>الوحدة</label><input id="tu" dir="ltr" value="${esc(t.unit)}"></div></div>
 <div class="row"><div class="grow"><label>الحد الأدنى</label><input id="tl" type="number" step="any" value="${esc(t.low)}"></div><div class="grow"><label>الحد الأعلى</label><input id="th" type="number" step="any" value="${esc(t.high)}"></div></div>
 <div class="muted" style="margin-top:8px">لو المدى مختلف للسيدات، اكتبه هنا (اختياري):</div>
 <div class="row"><div class="grow"><label>أدنى (سيدات)</label><input id="tlf" type="number" step="any" value="${esc(t.lowF)}"></div><div class="grow"><label>أعلى (سيدات)</label><input id="thf" type="number" step="any" value="${esc(t.highF)}"></div></div>
 <div class="muted" style="margin-top:8px">مدى الرضع (اختياري). لو فاضي، التحليل بيطلع بدون مدى وبدون علامة H/L للرضيع، وكمان أي رضيع أقل من ٦ أيام. مفيش مدى للبالغين بيتطبق عليهم.</div>
 <div class="row"><div class="grow"><label>رضيع من ٦ لـ ٣٠ يوم أدنى</label><input id="tln" type="number" step="any" value="${esc(t.lowN??'')}"></div><div class="grow"><label>أعلى</label><input id="thn" type="number" step="any" value="${esc(t.highN??'')}"></div></div>
 <div class="row"><div class="grow"><label>رضيع من ٣١ يوم لأقل من سنة أدنى</label><input id="tli" type="number" step="any" value="${esc(t.lowI??'')}"></div><div class="grow"><label>أعلى</label><input id="thi" type="number" step="any" value="${esc(t.highI??'')}"></div></div></div>
 <div id="tn2"><label>القيمة الطبيعية (تظهر تلقائي، وأي اختلاف يتعلّم)</label><input id="tno" value="${esc(t.normal)}" placeholder="Negative"></div>
 <div class="row" style="margin-top:14px"><button class="btn grow" onclick="tSave('${id||''}')">حفظ</button>${id?`<button class="btn d" onclick="tDel('${id}')">حذف</button>`:''}<button class="btn s" onclick="closeM()">إلغاء</button></div></div></div>`;tt();if(!id)$('tn').focus()}
function tt(){const n=$('ty').value==='num';$('tn1').style.display=n?'':'none';$('tn2').style.display=n?'none':''}
function tSave(id){const name=$('tn').value.trim();if(!name){toast('اكتب اسم التحليل');return}
 const d={name,cat:$('tc').value,price:$('tpr').value===''?0:+$('tpr').value,type:$('ty').value,unit:$('tu').value.trim(),low:$('tl').value,high:$('th').value,lowF:$('tlf').value,highF:$('thf').value,lowN:$('tln').value,highN:$('thn').value,lowI:$('tli').value,highI:$('thi').value,normal:$('tno').value.trim(),rdef:0};
 if(d.type==='txt'){d.unit='';d.low=d.high=d.lowF=d.highF=d.lowN=d.highN=d.lowI=d.highI=''}else d.normal='';
 if(id)Object.assign(S.tests.find(x=>x.id===id),d);else{d.id=uid('t');S.tests.push(d)}save();closeM();listC();toast('تم الحفظ')}
function tDel(id){if(!confirm('تحذف التحليل من القائمة؟ النتائج القديمة مش هتتأثر.'))return;S.tests=S.tests.filter(x=>x.id!==id);save();closeM();listC()}

/* ============ ملصقات الأنابيب ============ */
const C39={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','*':'nwnnwnwnn'};
function bars(c,code,x,y,w,h){const t='*'+code+'*';let u=0;t.split('').forEach(ch=>{u+=C39[ch].split('').reduce((a,e)=>a+(e==='w'?3:1),0)+1});u-=1;const m=w/u;let cx=x;c.fillStyle='#000';
 t.split('').forEach(ch=>{C39[ch].split('').forEach((e,i)=>{const ww=(e==='w'?3:1)*m;if(i%2===0)c.fillRect(cx,y,ww,h);cx+=ww});cx+=m})}
function tubeOf(it){const t=S.tests.find(x=>x.id===it.tid)||{},n=it.name||'',sp=t.spec||'';
 if(/^urine/i.test(n)||/urine/i.test(sp)&&!/serum|blood/i.test(sp))return'Urine';if(/^stool/i.test(n)||/stool/i.test(sp))return'Stool';if(/CSF/i.test(sp))return'CSF';
 if(/EDTA/i.test(sp))return'EDTA';if(/citrat/i.test(sp))return'Citrate';if(/heparin/i.test(sp))return'Heparin';if(/fluoride/i.test(sp))return'Fluoride';
 if(it.cat==='cbc'||/^(ESR|HbA1c|Blood group|Hb electro)/i.test(n))return'EDTA';if(/^(PT\b|INR|prothrombin|activated partial|aPTT|D-dimer|thrombin|factor|fibrinogen)/i.test(n))return'Citrate';return'Serum'}
function tubeLabels(v,p){const g={};v.items.forEach(i=>{const k=tubeOf(i);(g[k]=g[k]||[]).push(i)});if(!v.no){v.no=newNo(v.date);save()}
 return Object.keys(g).map(k=>{const cv=document.createElement('canvas');cv.width=600;cv.height=360;const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,600,360);c.strokeStyle='#bbb';c.lineWidth=2;c.strokeRect(1,1,598,358);
  c.fillStyle='#000';c.direction=/[\u0600-\u06ff]/.test(p.name)?'rtl':'ltr';c.textAlign='left';let fs=38;c.font='bold '+fs+'px '+FONT;while(c.measureText(p.name).width>560&&fs>20){fs-=2;c.font='bold '+fs+'px '+FONT}c.fillText(p.name,20,50);
  c.direction='ltr';c.font='24px '+FONT;c.fillText((hasAge(p)?ageSh(p)+' ':'')+(p.gender==='F'?'F':p.gender==='M'?'M':'')+'   '+fd(v.date),20,88);
  bars(c,v.no,40,104,520,120);c.textAlign='center';c.font='bold 30px '+FONT;c.fillText(v.no,300,260);
  c.textAlign='left';c.font='bold 28px '+FONT;c.fillText(k+' (auto)',20,320);c.textAlign='right';c.font='22px '+FONT;c.fillText(g[k].length+(g[k].length>1?' tests':' test'),580,320);return cv})}
function lblForm(id){$('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeM()"><div><h2>ملصقات الأنابيب</h2><div class="muted">بيتعمل ملصق لكل نوع أنبوبة (حسب نوع العينة) عليه الاسم والتاريخ وباركود برقم الزيارة. اكتب رقم الزيارة في خانة البحث أو اسكانه بالباركود سكانر عشان تفتح المريض.</div>
 <div class="card" style="background:#fff3cd;color:#6b5300">⚠ نوع الأنبوبة على الملصق تخمين تلقائي (من نوع العينة المسجل أو اسم التحليل). راجعه على العينة الحقيقية قبل ما تستخدم الملصق.</div><label class="chk"><input type="checkbox" id="lck"><span>راجعت أنواع الأنابيب</span></label><label>عدد النسخ لكل أنبوبة</label><input id="lcn" type="number" min="1" max="10" value="1">
 <div class="row" style="margin-top:12px"><button class="btn grow" onclick="lblGo('${id}',0)">طابعة ملصقات 50×30 مم</button><button class="btn s grow" onclick="lblGo('${id}',1)">ورقة A4 (ملصقات متعددة)</button><button class="btn s" onclick="closeM()">إلغاء</button></div></div></div>`}
async function lblGo(id,a4){if(!$('lck').checked){toast('أكد إنك راجعت أنواع الأنابيب');return}const v=S.visits.find(x=>x.id===id),p=S.patients.find(x=>x.id===v.pid);const n=Math.max(1,Math.min(10,+$('lcn').value||1));
 const w=IOS?null:window.open('','_blank');if(w)w.document.write('<p style="font:20px sans-serif;direction:rtl;padding:20px">جاري تجهيز الملصقات...</p>');
 const L=tubeLabels(v,p),all=[];L.forEach(l=>{for(let i=0;i<n;i++)all.push(l)});let pages,blob;
 if(!a4){pages=all;blob=await makePDF(pages,141.73,85.04)}
 else{pages=[];const cw=Math.round(66*W/210),ch=Math.round(cw*0.6),cols=3,rows=Math.floor((H-60)/ch);const per=cols*rows;
  for(let k=0;k<all.length;k+=per){const cv=document.createElement('canvas');cv.width=W;cv.height=H;const c=cv.getContext('2d');c.fillStyle='#fff';c.fillRect(0,0,W,H);
   all.slice(k,k+per).forEach((l,i)=>c.drawImage(l,Math.round((W-cols*cw)/2)+(i%cols)*cw,30+Math.floor(i/cols)*ch,cw-6,ch-6));pages.push(cv)}
  blob=await makePDF(pages)}
 const url=URL.createObjectURL(blob);closeM();if(w){w.location.href=url;toast(a4?'اطبع A4 بحجم فعلي 100%':'اطبع بحجم الملصق 50×30 وحجم فعلي 100%')}else pdfOut(blob,'labels.pdf')}

/* ============ الإعدادات والنسخ الاحتياطي ============ */
function vSettings(){const s=S.settings;
 $('app').innerHTML=`<div class="card"><h2 style="margin-top:0">بيانات المعمل (تظهر في التقرير)</h2>
 <label>اسم المعمل</label><input id="s1" value="${esc(s.name)}"><label>التليفون</label><input id="s2" value="${esc(s.phone)}"><label>مواعيد العمل</label><input id="s3" value="${esc(s.hours)}">
 <label>اسم المسؤول / الدكتور</label><input id="s4" value="${esc(s.owner)}"><label>سطر أسفل التقرير</label><input id="s5" value="${esc(s.footer)}">
 <label>الطباعة على ورق عليه اللوجو: مسافة فاضية من فوق (مم)</label><input id="s6" type="number" inputmode="decimal" value="${esc(s.lhTop||50)}"><label>مسافة فاضية من تحت (مم)</label><input id="s7" type="number" inputmode="decimal" value="${esc(s.lhBot||25)}">
 <button class="btn" style="margin-top:12px" onclick="sSave()">حفظ</button></div>
 <div class="card"><h2 style="margin-top:0">نسخة احتياطية</h2><div class="muted">البيانات متخزنة على الجهاز ده بس. للانتقال بين الأجهزة: احفظ نسخة، ابعتها لنفسك (واتساب)، وافتحها على الجهاز التاني بزر "دمج" (بيضيف الجديد بس من غير ما يمسح حاجة). اعمل نسخة احتياطية كل فترة، وابعتها لنفسك على واتساب. تقدر تفتحها على أي جهاز تاني.</div>
 <div class="row" style="margin-top:10px"><button class="btn" onclick="exp()">⬇ حفظ نسخة احتياطية</button><button class="btn s" onclick="toast('استيراد البيانات الحقيقية متوقف: نسخة تجريبية لحد ما نختار جهاز مدعوم')">🔀 دمج نسخة من جهاز تاني</button><button class="btn s" onclick="toast('استيراد البيانات الحقيقية متوقف: نسخة تجريبية لحد ما نختار جهاز مدعوم')">⬆ استرجاع (استبدال)</button><input type="file" id="imp" accept=".json" style="display:none" onchange="imp(this)"></div>
 <div class="muted" style="margin-top:10px">${S.patients.length} مريض - ${S.visits.length} زيارة - ${S.tests.length} تحليل</div></div>
 <div class="card"><button class="btn d sm" onclick="rst()">إرجاع قائمة التحاليل للوضع الأصلي</button></div>`}
function sSave(){Object.assign(S.settings,{name:$('s1').value,phone:$('s2').value,hours:$('s3').value,owner:$('s4').value,footer:$('s5').value,lhTop:Math.max(0,+$('s6').value||50),lhBot:Math.max(0,+$('s7').value||25)});save();toast('تم الحفظ')}
function dl(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(a.href)},90000)}
const IOS=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
function pdfOut(blob,name){const u=URL.createObjectURL(blob);window._pf=new File([blob],name,{type:'application/pdf'});$('modal').innerHTML=`<div class="modal" onclick="if(event.target===this)closeM()"><div><h2>الملف جاهز</h2><div class="row"><a class="btn w grow" href="${u}" target="_blank" style="text-align:center;text-decoration:none">📄 افتح الملف للطباعة</a></div><div class="row" style="margin-top:8px"><button class="btn s grow" onclick="navigator.share&&navigator.share({files:[window._pf]}).catch(()=>{})">مشاركة / حفظ</button><button class="btn s" onclick="closeM()">إغلاق</button></div><div class="muted" style="margin-top:8px">اطبع بورق A4 وحجم فعلي 100%</div></div></div>`}
function exp(){dl(new Blob([JSON.stringify(S)],{type:'application/json'}),'alfarid-backup-'+today()+'.json');toast('تم تنزيل النسخة')}
let mrg=0;
function merge(d){const add=(k)=>{const ids=new Set(S[k].map(x=>x.id));d[k].forEach(x=>{if(!ids.has(x.id))S[k].push(x)})};add('patients');add('visits');add('tests');S.seq=Math.max(S.seq||0,d.seq||0)}
function imp(el){el.value='';toast('الاستيراد متوقف في النسخة التجريبية');return;const f=el.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{const d=JSON.parse(r.result);if(!d.patients||!d.visits||!d.tests)throw 0;
 if(mrg){merge(d);save();toast('تم الدمج');go('patients');el.value='';return}
 if(!confirm('هتستبدل كل البيانات الحالية ببيانات النسخة ('+d.patients.length+' مريض). متأكد؟'))return;S=d;save();toast('تم الاسترجاع');go('patients')}catch(e){alert('الملف ده مش نسخة احتياطية صحيحة')}};r.readAsText(f)}
function rst(){if(!confirm('هترجع قائمة التحاليل للأصل وتمسح تعديلاتك عليها (المرضى مش هيتأثروا). متأكد؟'))return;S.tests=seed();mergeCat(true);toast('تم')}

/* ============ التقرير: رسم على canvas ثم PDF ============ */
/* ملاحظات تفسيرية آلية (للطبيب) */

const CMLIB=[
{t:'Lipid profile',re:/cholesterol|\bLDL|\bHDL|triglycer|lipid/i,x:"Interpret in the context of the patient's total cardiovascular risk. Per the 2019 ESC/EAS Guidelines for the management of dyslipidaemias, LDL-C goals are: <55 mg/dL (1.4 mmol/L) with at least a 50% reduction from baseline for very-high-risk patients; <70 mg/dL (1.8 mmol/L) for high risk; <100 mg/dL (2.6 mmol/L) for moderate risk; <116 mg/dL (3.0 mmol/L) for low risk. Non-HDL-C goals are <85, <100 and <130 mg/dL for very-high, high and moderate risk. Triglycerides below 150 mg/dL are desirable. A non-fasting sample is acceptable for risk assessment."},
{t:'Glucose',re:/glucose|\bFBS\b|\bRBS\b|blood sugar|OGTT|postprandial/i,x:"Per the ADA Standards of Care in Diabetes, diabetes is diagnosed by fasting plasma glucose of 126 mg/dL (7.0 mmol/L) or higher, a 2-hour plasma glucose of 200 mg/dL (11.1 mmol/L) or higher during a 75 g OGTT, or a random glucose of 200 mg/dL or higher with classic symptoms. Fasting glucose of 100-125 mg/dL indicates impaired fasting glucose (prediabetes). Without unequivocal hyperglycemia, the diagnosis should be confirmed with a repeat test. Fasting means no caloric intake for at least 8 hours."},
{t:'HbA1c',re:/hba1c|glycated|glycosylated|\bA1c\b/i,x:"Per the ADA Standards of Care in Diabetes, HbA1c of 6.5% (48 mmol/mol) or higher is consistent with diabetes, and 5.7-6.4% (39-47 mmol/mol) with prediabetes, to be confirmed by repeat testing when there are no clear symptoms. A common treatment goal for many non-pregnant adults with diabetes is below 7.0% (53 mmol/mol), individualized for each patient. HbA1c may be unreliable in anemia, hemoglobin variants, or after recent transfusion."},
{t:'Liver function',re:/\bALT\b|\bAST\b|SGPT|SGOT|\bALP\b|alkaline phosph|\bGGT\b|bilirubin/i,x:"Evaluate per the ACG Clinical Guideline on the Evaluation of Abnormal Liver Chemistries (2017). Classify the pattern as hepatocellular (ALT/AST predominant), cholestatic (ALP predominant) or mixed. Mild elevations (below 5 times the upper limit of normal) are common and are often related to fatty liver disease, medications or alcohol. An AST:ALT ratio above 2 may suggest alcohol-related liver disease. Persistent abnormalities call for repeat testing and clinical assessment."},
{t:'Kidney function',re:/creatinine|\burea\b|\bBUN\b|eGFR/i,x:"Per the KDIGO 2012 CKD guideline, chronic kidney disease is defined by eGFR below 60 mL/min/1.73 m2 and/or markers of kidney damage persisting for more than 3 months. GFR categories: G1 90 or above, G2 60-89, G3a 45-59, G3b 30-44, G4 15-29, G5 below 15. Serum creatinine depends on muscle mass, diet and hydration, so eGFR should be used and an abnormal result confirmed by repeat testing. Albuminuria (urine albumin/creatinine ratio) should be assessed to stage risk."},
{t:'Thyroid function',re:/\bTSH\b|\bT3\b|\bT4\b|\bFT3\b|\bFT4\b|thyroxine|free T/i,x:"TSH is the most sensitive screening test and should be read together with free T4 (and free T3 when needed). A raised TSH with low free T4 indicates overt primary hypothyroidism; a raised TSH with normal free T4 is subclinical hypothyroidism, usually confirmed by repeating the tests after 2-3 months (ATA/AACE guidelines for hypothyroidism, 2012). A suppressed TSH with raised free T4/T3 indicates hyperthyroidism (ATA guidelines for hyperthyroidism, 2016). Reference intervals vary with the assay and in pregnancy."},
{t:'Complete blood count',re:/hemoglobin|\bHb\b|\bHGB\b|\bRBC|\bWBC|platelet|\bPLT\b|\bMCV\b|hematocrit|\bHCT\b/i,x:"Anemia is defined by the WHO as hemoglobin below 13.0 g/dL in men, below 12.0 g/dL in non-pregnant women and below 11.0 g/dL in pregnant women (WHO, 2011). Classify by MCV: low MCV (microcytic) suggests iron deficiency or thalassemia trait; normal MCV suggests chronic disease, blood loss or hemolysis; high MCV (macrocytic) suggests vitamin B12 or folate deficiency, liver disease, hypothyroidism or drugs. Platelets below 150 x10^9/L or abnormal white cell counts should be correlated clinically, with a blood film review where indicated."},
{t:'Iron status',re:/ferritin|\biron\b|\bTIBC\b/i,x:"Per the WHO 2020 guideline on ferritin concentrations, a ferritin below 15 ug/L in adults indicates depleted iron stores; in the presence of infection or inflammation the threshold is below 70 ug/L, since ferritin is an acute-phase reactant. Interpret together with hemoglobin, MCV and transferrin saturation."},
{t:'Vitamin D',re:/vitamin ?D|25.?OH/i,x:"Per the Endocrine Society clinical practice guideline (2011), vitamin D deficiency is a 25-OH vitamin D level below 20 ng/mL (50 nmol/L) and insufficiency is 21-29 ng/mL. Thresholds differ between societies, so interpret with the clinical context."},
{t:'Urinalysis',re:/^Urine -|urinalysis/i,x:"Interpret with the clinical picture and a properly collected midstream sample. Pyuria with positive nitrite or leukocyte esterase supports a urinary tract infection; confirm with urine culture when clinically indicated (IDSA/ESCMID 2010 guideline; EAU Urological Infections guidelines). Persistent hematuria or proteinuria should be repeated and quantified, and the patient evaluated for kidney or urinary tract disease (KDIGO 2012 CKD guideline). Glucose or ketones in urine should be correlated with blood glucose."},
{t:'Stool analysis',re:/^Stool -|stool analysis|parasit|occult/i,x:"A single stool sample can miss intermittent parasite shedding, so examining samples from several days increases sensitivity (CDC DPDx guidance). Pus cells with blood and mucus suggest an invasive or inflammatory process, and culture may be needed. A positive occult blood test needs clinical evaluation and does not identify the source of bleeding; for colorectal cancer screening, a fecal immunochemical test (FIT) is preferred (US Multi-Society Task Force on Colorectal Cancer, 2017)."},
{t:'Inflammatory markers (CRP / ESR)',re:/\bCRP\b|C.?reactive|\bESR\b|sedimentation/i,x:"CRP and ESR are non-specific markers of inflammation and cannot establish a diagnosis. CRP rises and falls faster than ESR. ESR is affected by anemia, age and sex. For cardiovascular risk, hs-CRP below 1 mg/L is low risk, 1-3 mg/L average and above 3 mg/L high, and a value above 10 mg/L should be repeated and an infectious or inflammatory cause sought (AHA/CDC scientific statement, 2003)."},
{t:'Electrolytes',re:/^(Sodium|Potassium|Chloride)\b|^(Na|K)\b ?\(|^(Na|K) \(/i,x:"Hyponatremia is a sodium below 135 mmol/L (mild 130-134, moderate 125-129, profound below 125) and needs assessment of volume status and osmolality (European clinical practice guideline on hyponatraemia, 2014). Hypokalemia is a potassium below 3.5 mmol/L. Hyperkalemia is above 5.0-5.5 mmol/L, graded mild 5.5-5.9, moderate 6.0-6.4 and severe 6.5 or above (UK Kidney Association, 2020). Hemolysis or delayed serum separation can falsely raise potassium, so unexpected results should be repeated."},
{t:'Calcium, phosphorus and magnesium',re:/^(Calcium|Phosphorus|Magnesium)\b|^(Ca|Mg) \(/i,x:"Serum calcium should be interpreted with albumin (corrected calcium) and, when abnormal, with PTH and vitamin D. Phosphorus is raised in reduced kidney function and low in vitamin D deficiency or hyperparathyroidism. Low magnesium can cause refractory low potassium and calcium. Abnormal values should be confirmed on a repeat sample (KDIGO CKD-MBD guideline, 2017, for patients with kidney disease)."},
{t:'Uric acid',re:/^Uric Acid$/i,x:"Hyperuricemia is a serum urate above 6.8 mg/dL (the limit of urate solubility). In patients with gout on urate-lowering therapy the treat-to-target goal is below 6 mg/dL (ACR Guideline for the Management of Gout, 2020). Many people with a raised urate never develop gout, so treatment decisions depend on symptoms."},
{t:'Coagulation',re:/Prothrombin Time|^INR$|^aPTT$|\bPTT\b|D-Dimer/i,x:"For patients on warfarin, an INR of 2.0-3.0 is the usual target for most indications (CHEST antithrombotic guidelines, 2012). A prolonged PT or aPTT should be evaluated for factor deficiency, liver disease, vitamin K deficiency or an inhibitor, and a mixing study can help. A normal D-dimer helps to exclude venous thromboembolism in low-risk patients, but a raised D-dimer is non-specific (ISTH/ESC guidance)."},
{t:'Cardiac markers',re:/troponin|^CK-?MB/i,x:"Per the Fourth Universal Definition of Myocardial Infarction (ESC/ACC/AHA/WHF, 2018), myocardial injury is shown by a cardiac troponin value above the 99th percentile upper reference limit, and an acute event is indicated by a rise and/or fall of troponin with clinical evidence of ischemia. Troponin can also be raised in kidney failure, myocarditis, sepsis and heart failure. Serial measurements are needed, and results must be read with the ECG and symptoms."},
{t:'Vitamin B12 and folate',re:/Vitamin B12|^Folate|Folic acid in serum/i,x:"Per the British Society for Haematology guideline on cobalamin and folate disorders (2014), a serum B12 below about 200 ng/L (148 pmol/L) suggests deficiency, and borderline values may need methylmalonic acid or homocysteine to confirm. A low serum folate is below about 3 ug/L (7 nmol/L). Treat B12 deficiency before or together with folate to avoid worsening neurological damage."},
{t:'Viral hepatitis and HIV screening',re:/^HBsAg|^HCV|^HIV|HBs A[bg]|hepatitis/i,x:"A reactive screening result must be confirmed. A positive HBsAg should be followed by HBV DNA, HBeAg/anti-HBe and liver tests (EASL HBV guidelines, 2017). A positive anti-HCV should be confirmed with HCV RNA to separate current from past infection (EASL HCV recommendations, 2020). A reactive HIV antigen/antibody screen requires confirmatory testing following the national algorithm (WHO consolidated HIV testing guidelines). A negative result in the window period does not exclude recent infection."},
{t:'Tumor markers',re:/^PSA|^CEA$|^AFP|^Ca \d|^CA ?\d|tumor marker/i,x:"Tumor markers lack the sensitivity and specificity needed to screen for or diagnose cancer. They are mainly used to monitor known disease and response to treatment, and mild rises occur in benign conditions. A raised PSA needs clinical context, age-specific interpretation, and repeat testing before further investigation. All results should be correlated with imaging and clinical evaluation (NACB laboratory medicine practice guidelines for tumor markers, 2008)."},
{t:'Semen analysis',re:/^Semen/i,x:"Interpret against the WHO Laboratory Manual for the Examination and Processing of Human Semen, 6th edition (2021). Lower reference limits (5th percentile): volume 1.4 mL, sperm concentration 16 million/mL, total sperm number 39 million, total motility 42%, progressive motility 30%, vitality 54%, normal forms 4%. Because semen quality varies, an abnormal result should be repeated after 2-3 months with 2-7 days of abstinence."}
];
function cbcSimple(items){const lo=[],hi=[];(items||[]).forEach(i=>{if(!i.imp||!i.pr)return;const x=parseFloat(i.value),l=parseFloat(i.pr.l),h=parseFloat(i.pr.h);if(isNaN(x))return;const n=String(i.name).replace(/ \(.*\)/,'');if(!isNaN(l)&&x<l)lo.push(n);else if(!isNaN(h)&&x>h)hi.push(n)});
 if(!lo.length&&!hi.length)return 'All reported CBC values are within the printed reference ranges.';return 'Compared with the printed reference ranges: '+(lo.length?'below range: '+lo.join(', ')+'. ':'')+(hi.length?'above range: '+hi.join(', ')+'. ':'')+'The other values are within range. Please interpret with the clinical picture.'}
function autoCm(items){if((items||[]).length&&items.every(i=>i.cat==='uri'||i.cat==='sto'))return '';if((items||[]).filter(i=>i.imp&&i.cat==='cbc'&&String(i.value||'').trim()).length>=15)return cbcSimple(items);const o=[];CMLIB.forEach(e=>{const sp=/^(Urinalysis|Stool analysis)$/.test(e.t);if((items||[]).some(i=>String(i.value||'').trim()&&(sp||!/^(Urine|Stool) - /i.test(i.name||''))&&e.re.test(i.name||'')))o.push(e.t+': '+e.x)});if(!o.length&&(items||[]).length)o.push('General: Results should be interpreted together with the clinical findings, the patient history and the reference ranges of the method used. Abnormal or unexpected results may need repeat testing or further evaluation (ISO 15189 medical laboratory requirements).');return o.join('\n\n')}

